web/app.js.text:
let defaults = {};
let curveEditors = null;
let lastResult = null;
let help = {};
let debugPage = 0;
let latestDerived = null;
let derivedSequence = 0;
let readoutModes = {};
let algorithmConfig = {};
let lastPerformance = null;
let histogramView = null;
let disposeHistogramOverview = null;
let performanceInputSnapshot = null;
const isDebug = location.pathname === "/debug";

const $ = (id) => document.getElementById(id);
const inputEls = () => [...document.querySelectorAll("[data-key]")];
const colors = { cyan: "#41d9d0", blue: "#659cff", orange: "#ffb55b", muted: "#8da0b3", grid: "#243244" };

function fillForm(config) {
  inputEls().forEach(el => { if (config[el.dataset.key] !== undefined) {
    if(el.type==='checkbox')el.checked=config[el.dataset.key];else el.value=LidarUnits.display(config[el.dataset.key],el.dataset.key);
  }});
  curveEditors.fill(config.spectral_inputs);
}

function collectConfig() {
  const cfg = { ...defaults };
  inputEls().forEach(el => {
    const key = el.dataset.key;
    const isInteger = ["H_binning", "V_binning", "laser_shots", "monte_carlo_trials", "readout_mean_trials", "noise_mean_trials", "rng_seed", "line_channels"].includes(key);
    if(el.type==='checkbox')cfg[key]=el.checked;
    else if (el.tagName === 'SELECT') {
      if (!el.value || !Array.from(el.options).some(option=>option.value===el.value)) throw new Error(`参数 ${key} 需要选择有效选项，请刷新页面后重试。`);
      cfg[key] = el.value;
    } else {
      cfg[key] = LidarUnits.canonical(Number(el.value),key);
      if (el.value.trim() === '' || !Number.isFinite(cfg[key]) || (isInteger && !Number.isInteger(cfg[key]))) throw new Error(`参数 ${key} 需要有效${isInteger ? '整数' : '数值'}`);
    }
  });
  cfg.spectral_inputs = curveEditors.values();
  return cfg;
}

function fmt(x, digits=3) {
  if (!Number.isFinite(x)) return "—";
  if (Math.abs(x) >= 1e5 || (Math.abs(x) > 0 && Math.abs(x) < 1e-3)) return x.toExponential(2);
  return x.toFixed(digits);
}

function setupCanvas(canvas) {
  const dpr = window.devicePixelRatio || 1;
  const cssW = canvas.clientWidth;
  const cssH = Number(canvas.dataset.logicalHeight || canvas.getAttribute("height"));
  canvas.dataset.logicalHeight = cssH;
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  const ctx = canvas.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return { ctx, w: cssW, h: cssH };
}

function niceTicks(min, max, count=5) {
  if (!(max > min)) return [min];
  const raw = (max-min)/count;
  const pow = Math.pow(10, Math.floor(Math.log10(raw)));
  const n = raw/pow;
  const step = (n < 1.5 ? 1 : n < 3 ? 2 : n < 7 ? 5 : 10) * pow;
  const start = Math.ceil(min/step)*step;
  const out = [];
  for (let v=start; v<=max+step*0.01; v+=step) out.push(v);
  return out;
}

function drawLines(canvas, x, series, opts={}) {
  const {ctx,w,h} = setupCanvas(canvas);
  const pad = {l:58,r:18,t:18,b:40};
  const pw=w-pad.l-pad.r, ph=h-pad.t-pad.b;
  const i0=opts.i0 ?? 0, i1=opts.i1 ?? x.length;
  const xx=x.slice(i0,i1);
  const sliced=series.map(s => ({...s, x:s.x||xx, y:s.x?s.y:s.y.slice(i0,i1),lower:s.lower?.slice(i0,i1)}));
  const dx = opts.binWidth || 0;
  const xmin=opts.edges ? opts.edges[i0] : Math.min(...xx)-dx/2;
  const xmax=opts.edges ? opts.edges[i1] : Math.max(...xx)+dx/2;
  let ymin=opts.ymin ?? 0;
  let ymax=opts.ymax ?? sliced.reduce((m,s)=>s.y.reduce((v,y,i)=>Number.isFinite(y)&&s.x[i]>=xmin&&s.x[i]<=xmax?Math.max(v,y):v,m),1)*1.08;
  const sx=v=>pad.l+(v-xmin)/(xmax-xmin||1)*pw;
  const sy=v=>pad.t+ph-(v-ymin)/(ymax-ymin||1)*ph;
  ctx.clearRect(0,0,w,h);
  ctx.font="11px ui-monospace, Consolas";
  ctx.fillStyle=(globalThis.LidarTheme?.color(colors.muted) ?? (colors.muted)); ctx.strokeStyle=(globalThis.LidarTheme?.color(colors.grid) ?? (colors.grid)); ctx.lineWidth=1;
  niceTicks(xmin,xmax,6).forEach(v=>{ const px=sx(v); ctx.beginPath();ctx.moveTo(px,pad.t);ctx.lineTo(px,pad.t+ph);ctx.stroke();ctx.fillText(fmt(v, opts.xDigits??1),px-12,h-18); });
  niceTicks(ymin,ymax,5).forEach(v=>{ const py=sy(v);ctx.beginPath();ctx.moveTo(pad.l,py);ctx.lineTo(w-pad.r,py);ctx.stroke();ctx.fillText(fmt(v, opts.yDigits ?? (v<10?2:0)),6,py+4); });
  sliced.forEach(s=>{
    if (s.bars) {
      ctx.fillStyle=(globalThis.LidarTheme?.color(s.color) ?? (s.color)); ctx.globalAlpha=0.75;
      const width = opts.binWidth || (xx.length > 1 ? xx[1]-xx[0] : 1);
      ctx.save(); ctx.beginPath(); ctx.rect(pad.l,pad.t,pw,ph); ctx.clip();
      for(let i=0;i<xx.length;i++) {
        const left=opts.edges ? opts.edges[i0+i] : xx[i]-width/2;
        const right=opts.edges ? opts.edges[i0+i+1] : xx[i]+width/2;
        ctx.fillRect(sx(left),sy(s.y[i]),Math.max(0.5,(right-left)/(xmax-xmin)*pw*0.9),sy(0)-sy(s.y[i]));
      }
      ctx.restore(); ctx.globalAlpha=1; return;
    }
    ctx.save();ctx.beginPath();ctx.rect(pad.l,pad.t,pw,ph);ctx.clip();
    ctx.strokeStyle=(globalThis.LidarTheme?.color(s.color) ?? (s.color));ctx.fillStyle=(globalThis.LidarTheme?.color(s.color) ?? (s.color));ctx.lineWidth=s.width||1.5;ctx.globalAlpha=s.alpha||1;
    if(s.errorBars){
      ctx.lineWidth=1.2;
      s.x.forEach((v,i)=>{
        if(v<xmin||v>xmax||!Number.isFinite(s.y[i])||!Number.isFinite(s.lower[i]))return;
        const cap=Math.min(4,Math.max(0.3,(sx(v+(opts.binWidth||1))-sx(v))*0.28));
        const px=sx(v),lo=sy(s.lower[i]),hi=sy(s.y[i]);
        ctx.beginPath();ctx.moveTo(px,lo);ctx.lineTo(px,hi);
        ctx.moveTo(px-cap,lo);ctx.lineTo(px+cap,lo);ctx.moveTo(px-cap,hi);ctx.lineTo(px+cap,hi);ctx.stroke();
      });
    }else if(s.points){
      s.x.forEach((v,i)=>{if(v<xmin||v>xmax||!Number.isFinite(s.y[i]))return;ctx.beginPath();ctx.arc(sx(v),sy(s.y[i]),3.5,0,2*Math.PI);ctx.fill();});
    }else{
      ctx.setLineDash(s.dash||[]);ctx.beginPath();
      for(let i=0;i<s.x.length;i++){const px=sx(s.x[i]),py=sy(s.y[i]);if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);}
      ctx.stroke();
    }
    ctx.restore();
  });
  ctx.fillStyle=(globalThis.LidarTheme?.color(colors.muted) ?? (colors.muted)); ctx.textAlign="center"; ctx.fillText(opts.xLabel||"",pad.l+pw/2,h-4);ctx.textAlign="left";
  let lx=pad.l+6;
  sliced.forEach(s=>{
    ctx.save();ctx.fillStyle=(globalThis.LidarTheme?.color(s.color) ?? (s.color));ctx.strokeStyle=(globalThis.LidarTheme?.color(s.color) ?? (s.color));
    if(s.errorBars){ctx.beginPath();ctx.moveTo(lx+6,pad.t);ctx.lineTo(lx+6,pad.t+8);ctx.moveTo(lx+2,pad.t);ctx.lineTo(lx+10,pad.t);ctx.moveTo(lx+2,pad.t+8);ctx.lineTo(lx+10,pad.t+8);ctx.stroke();}
    else if(s.points){ctx.beginPath();ctx.arc(lx+6,pad.t+4,3,0,2*Math.PI);ctx.fill();}
    else{ctx.setLineDash(s.dash||[]);ctx.beginPath();ctx.moveTo(lx,pad.t+4);ctx.lineTo(lx+13,pad.t+4);ctx.stroke();}
    ctx.restore();ctx.fillStyle=(globalThis.LidarTheme?.color(colors.muted) ?? (colors.muted));ctx.fillText(s.name,lx+18,pad.t+7);lx+=ctx.measureText(s.name).width+34;
  });
  const scatterGroups=opts.scatterGroups || (opts.scatter ? [opts.scatter] : []);
  scatterGroups.filter(group=>group.x.length).forEach(group=>{
    const color=group.color||colors.blue, label=group.name||'原始采样点';
    ctx.save();ctx.beginPath();ctx.rect(pad.l,pad.t,pw,ph);ctx.clip();
    group.x.forEach((v,i)=>{
      ctx.beginPath();ctx.arc(sx(v),sy(group.y[i]),5,0,2*Math.PI);
      ctx.fillStyle=(globalThis.LidarTheme?.color(color) ?? (color));ctx.fill();ctx.strokeStyle=(globalThis.LidarTheme?.color("#eef6ff") ?? ("#eef6ff"));ctx.lineWidth=1;ctx.stroke();
    });
    ctx.restore();ctx.fillStyle=(globalThis.LidarTheme?.color(color) ?? (color));ctx.beginPath();ctx.arc(lx+6,pad.t+4,4,0,2*Math.PI);ctx.fill();
    ctx.fillStyle=(globalThis.LidarTheme?.color(colors.muted) ?? (colors.muted));ctx.fillText(label,lx+18,pad.t+7);lx+=ctx.measureText(label).width+48;
  });
  if (opts.marker) {
    const px=sx(opts.marker.x),py=sy(opts.marker.y);
    ctx.save();ctx.strokeStyle=(globalThis.LidarTheme?.color(colors.orange) ?? (colors.orange));ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(px,pad.t+20);ctx.lineTo(px,pad.t+ph);ctx.stroke();ctx.setLineDash([]);
    ctx.fillStyle=(globalThis.LidarTheme?.color(colors.orange) ?? (colors.orange));ctx.beginPath();ctx.arc(px,py,4,0,2*Math.PI);ctx.fill();
    ctx.textAlign="center";ctx.fillText(opts.marker.label,Math.max(pad.l+70,Math.min(w-pad.r-70,px)),pad.t+18);ctx.restore();
  }
}

function drawRange(canvas, points) {
  const x=points.map(p=>p.range_m), counts=points.map(p=>p.signal_counts), snr=points.map(p=>p.shot_noise_snr);
  const {ctx,w,h}=setupCanvas(canvas); const pad={l:58,r:55,t:22,b:40}; const pw=w-pad.l-pad.r,ph=h-pad.t-pad.b;
  const xmin=Math.min(...x),xmax=Math.max(...x),ymax=Math.max(...counts)*1.08,smax=Math.max(...snr)*1.08;
  const sx=v=>pad.l+(v-xmin)/(xmax-xmin||1)*pw, sy=v=>pad.t+ph-v/(ymax||1)*ph, ss=v=>pad.t+ph-v/(smax||1)*ph;
  ctx.clearRect(0,0,w,h);ctx.font="11px ui-monospace, Consolas";ctx.strokeStyle=(globalThis.LidarTheme?.color(colors.grid) ?? (colors.grid));ctx.fillStyle=(globalThis.LidarTheme?.color(colors.muted) ?? (colors.muted));
  niceTicks(xmin,xmax,5).forEach(v=>{let px=sx(v);ctx.beginPath();ctx.moveTo(px,pad.t);ctx.lineTo(px,pad.t+ph);ctx.stroke();ctx.fillText(fmt(v,0),px-10,h-18)});
  niceTicks(0,ymax,5).forEach(v=>{let py=sy(v);ctx.beginPath();ctx.moveTo(pad.l,py);ctx.lineTo(w-pad.r,py);ctx.stroke();ctx.fillText(fmt(v,0),5,py+4)});
  const line=(arr,map,color)=>{ctx.beginPath();ctx.strokeStyle=(globalThis.LidarTheme?.color(color) ?? (color));ctx.lineWidth=2;arr.forEach((v,i)=>i?ctx.lineTo(sx(x[i]),map(v)):ctx.moveTo(sx(x[i]),map(v)));ctx.stroke();};
  line(counts,sy,colors.cyan);line(snr,ss,colors.orange);
  ctx.fillStyle=(globalThis.LidarTheme?.color(colors.muted) ?? (colors.muted));ctx.textAlign="center";ctx.fillText("距离 (m)",pad.l+pw/2,h-4);ctx.textAlign="left";
  ctx.fillStyle=(globalThis.LidarTheme?.color(colors.cyan) ?? (colors.cyan));ctx.fillText("信号累计计数",pad.l+6,pad.t+8);ctx.fillStyle=(globalThis.LidarTheme?.color(colors.orange) ?? (colors.orange));ctx.fillText("SNR（右轴）",pad.l+98,pad.t+8);ctx.fillStyle=(globalThis.LidarTheme?.color(colors.muted) ?? (colors.muted));ctx.fillText(fmt(smax,1),w-pad.r+8,pad.t+4);ctx.fillText("0",w-pad.r+8,pad.t+ph+4);
}

function drawHeatmap(canvas, matrix) {
  const {ctx,w,h}=setupCanvas(canvas); const n=matrix.length,pad={l:42,r:15,t:15,b:38}; const side=Math.min(w-pad.l-pad.r,h-pad.t-pad.b); const cw=side/n;
  const vals=matrix.flat();const max=Math.max(...vals,1e-12);
  ctx.clearRect(0,0,w,h);
  for(let row=0;row<n;row++)for(let col=0;col<n;col++){
    const t=Math.sqrt(matrix[row][col]/max); const r=Math.round(20+45*t),g=Math.round(31+186*t),b=Math.round(44+164*t);
    ctx.fillStyle=(globalThis.LidarTheme?.color(`rgb(${r},${g},${b})`) ?? (`rgb(${r},${g},${b})`));ctx.fillRect(pad.l+col*cw,pad.t+row*cw,cw+.4,cw+.4);
  }
  ctx.fillStyle=(globalThis.LidarTheme?.color(colors.muted) ?? (colors.muted));ctx.font="11px ui-monospace, Consolas";ctx.fillText("受扰",4,pad.t+side/2);ctx.textAlign="center";ctx.fillText("源通道",pad.l+side/2,h-6);ctx.textAlign="left";
  const step=Math.max(1,Math.ceil(n/8));for(let i=0;i<n;i+=step){ctx.fillText(String(i),pad.l+i*cw,pad.t+side+15);ctx.fillText(String(i),pad.l-25,pad.t+(i+.7)*cw);}
}

function addTextRows(target, rows) {
  target.replaceChildren(...rows.map(values=>{const row=document.createElement('tr');values.forEach(value=>{const cell=document.createElement('td');cell.textContent=value;row.append(cell);});return row;}));
}

function probabilityText(value) {
  if(!value||value.estimate==null)return '—（无样本/无信号）';
  return fmt(value.estimate*100,1)+'% ['+fmt(value.ci_lower*100,1)+', '+fmt(value.ci_upper*100,1)+']%';
}

function renderDetection(result) {
  const d=result.detection;
  if(!d.enabled){$('detectionStatus').textContent='检测门限关闭：距离仅为原始寻峰结果，未评估Pd/PFA。';$('detectionMetrics').replaceChildren();$('detectionAudit').textContent=d.note;return;}
  $('detectionStatus').textContent=(d.observed.detected?'已检出':'未检出')+'；评分 '+fmt(d.observed.score,4)+'，门限 '+fmt(d.threshold,4)+'（严格大于才接受）；原始寻峰 '+fmt(d.observed.raw_distance_m,3)+' m。全门 '+d.search_gate_ns.join('–')+' ns。';
  const rows=[['Pd：检测且命中真值容差',d.pd],['PFA：无目标全门虚警',d.pfa],['有信号工况触发比例（不限距离）',d.trigger_rate]].map(([label,v])=>[label,probabilityText(v),v?fmt(v.confidence*100,0)+'%精确二项区间；'+v.successes+'/'+v.trials:'无信号预算，不报告Pd']);
  rows.push(['校准与验证分离','目标PFA '+fmt(d.target_pfa*100,2)+'%',d.calibration.trials+'次校准；另'+d.null_evaluation.trials+'次无目标验证']);
  rows.push(['PFA目标核对',d.pfa_upper_within_target?'验证区间上限不超过目标':'尚不能确认达到目标','目标值不是保证值；需要同时查看独立验证区间。']);
  addTextRows($('detectionMetrics'),rows);
  $('detectionAudit').textContent=JSON.stringify(d,null,2);
}

function renderPerformance(result) {
  const p=result.points,x=p.map(v=>v.value);
  const series=[{name:'Pd（命中容差）',y:p.map(v=>v.pd?.estimate??NaN),color:colors.cyan,points:true},
                {name:'PFA',y:p.map(v=>v.pfa.estimate),color:colors.orange,points:true},
                {name:'Pd置信区间',y:p.map(v=>v.pd?.ci_upper??NaN),lower:p.map(v=>v.pd?.ci_lower??NaN),color:colors.cyan,errorBars:true},
                {name:'PFA置信区间',y:p.map(v=>v.pfa.ci_upper),lower:p.map(v=>v.pfa.ci_lower),color:colors.orange,errorBars:true}];
  drawLines($('performanceChart'),x,series,{xLabel:result.axis_label,ymin:0,ymax:1.05,yDigits:2});
  addTextRows($('performanceRows'),p.map(v=>[fmt(v.value,2),probabilityText(v.pd),probabilityText(v.pfa),fmt(v.failure_rate*100,1)+'%',fmt(v.bias_cm,2),fmt(v.precision_cm_1sigma,2),v.accepted_trials+'/'+v.trials,fmt(v.ideal_signal_candidates,2),fmt(v.mean_recorded_counts,2)]));
}

function setSweepDefaults() {
  const keys={range_m:'performance_sweep_range_values',solar_illuminance_lux:'performance_sweep_lux_values',laser_shots:'performance_sweep_shot_values'};
  $('performanceValues').value=algorithmConfig[keys[$('performanceAxis').value]].join(', ');
}

async function runPerformance() {
  $('runPerformance').disabled=true;
  try {
    const cfg=collectConfig(),axis=$('performanceAxis').value;
    const tokens=$('performanceValues').value.split(/[,，\s]+/).filter(Boolean);
    if(!tokens.length||tokens.some(v=>!Number.isFinite(Number(v))))throw new Error('请输入有效工况值');
    const values=tokens.map(Number);
    $('performanceStatus').textContent='正在按当前读出模式计算 '+values.length+' 个工况…';
    const result=await (await request('/api/performance-sweep',{configuration:cfg,axis,values})).json();
    lastPerformance=result;performanceInputSnapshot=JSON.stringify(cfg);renderPerformance(result);
