'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>BudgetNumbers.format(v);
const memorySize=v=>v==null?fmt(v):v>=2**30?fmt(v/2**30)+' GiB':v>=2**20?fmt(v/2**20)+' MiB':v>=1024?fmt(v/1024)+' KiB':fmt(v)+' B';
const get=(o,p)=>p.split('.').reduce((v,k)=>v[k],o);
const put=(o,p,v)=>{const ks=p.split('.');const k=ks.pop();get(o,ks.join('.'))[k]=v;};
const clone=o=>structuredClone(o);
const KEY='spad-hardware-budget-v1';
let catalog,config,editors,result=null,baseline=null,timer,revision=0,running=false,queued=false;
const displayFactors={'rx_channel.v_width_deg':Math.PI/180*1000,'system.spad.dcr_cps_per_spad':LidarUnits.displayFactor('system.spad.dcr_cps_per_spad')};
const enumNames={fixed_ab:'双缓冲 · 固定A采集/B处理',single:'单缓冲 · 串行复用',acquisition_end:'接收包络结束交接',slot_end:'slot结束交接',echo:'Echo回波窗口',points:'Range数据',histogram:'直方图',lanes:'逐链路lane速率',aggregate_net:'旧总净带宽',accumulated_column:'每列累积直方图',per_shot:'每发独立直方图',signal:'扣背景信号面积',total:'原始总计数面积',gaussian:'高斯',rectangular:'矩形脉冲',rectangle:'矩形孔径',circle:'圆形孔径',ellipse:'椭圆孔径',true:'开启',false:'关闭'};
const metricDefs={pulse_average_power_w:['单脉冲等效平均功率 · Tx前','W'],single_pulse_energy_nj:['派生单发能量 · Tx前','nJ'],vfov_deg:['系统垂直视场 VFOV','deg'],channel_power_w:['单通道功率','W'],channel_energy_nj:['单通道单发能量','nJ'],tx_channel_v_deg:['单通道Tx V全角','deg'],tx_channel_v_mrad:['单通道Tx V全角','mrad'],rx_channel_v_deg:['单通道Rx V全角','deg'],rx_channel_v_mrad:['单通道Rx V全角','mrad'],rx_channel_h_mrad:['单通道Rx H全角','mrad'],vertical_angle_step_deg:['V等角预算分区宽度','deg'],column_time_us:['每列可用时间','μs'],time_margin_us:['计入复位后余量','μs'],column_energy_nj:['每列光能 · Tx前','nJ'],average_optical_power_w:['整帧平均光功率 · Tx前','W'],acquisition_envelope_us:['多发接收包络','μs'],margin_without_reset_us:['未计复位时间余量','μs'],max_pulses_per_column:['时间容量最大发数','发/列'],max_frame_rate_hz:['时间容量最高帧率','Hz'],angle_step_deg:['水平采样间隔','deg'],required_optical_rad_s:['匀速扫描光学角速度','rad/s'],pulse_train_sweep_mrad:['首末发射角位移','mrad'],return_rotation_mrad:['飞行期间光学转角','mrad'],flight_ns:['物理往返飞行时间','ns'],gate_fraction:['单发门内光学份额','1'],pulse_count:['每列发数','发'],pulses_per_second:['平均发射次数','发/s'],average_output_power_w:['平均光功率 · Tx后','W'],peak_optical_power_w:['峰值光功率 · Tx前','W'],electric_power_w:['发光器件电输入估算','W'],emitter_heat_w:['发光器件非光损耗','W'],signal_candidates_per_column:['门内信号候选 / 列','次'],background_candidates_per_column:['光学背景候选 / 列','次'],device_noise_candidates_per_column:['器件噪声候选 / 列','次'],final_mixed_records:['最终混合记录','未仿真'],channels:['读出通道数','通道'],spads_per_channel:['H × V 聚合','SPAD/通道'],physical_spads:['物理阵列规模','SPAD'],histogram_bins:['每通道时间分箱','bin'],histogram_body_bytes:['直方图计数区','byte/列'],histogram_payload_bytes:['直方图含列头','byte/列'],average_payload_mbps:['含CSI-2的线速需求','Mbps'],wire_time_us:['当前格式单列发送','μs']};
async function request(url,body,text=false){const r=await fetch(url,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':text?'text/plain':'application/json'},body:text?body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));return d;}
function fail(e){$('error').hidden=false;$('error').textContent=e.message||String(e);}
function envelope(c){return {schema_version:7,kind:'hardware-budget',experiment:c};}
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),0);}
function fieldSchema(path){let s=catalog.schema;for(const part of path.split('.')){if(s.$ref)s=catalog.schema.$defs[s.$ref.split('/').pop()];s=s.properties[part];}return s;}
function helpIndex(tree,out={}){for(const [k,v]of Object.entries(tree)){if(v&&typeof v==='object'){if(v.label)out[k]=v;else helpIndex(v,out);}}return out;}
function buildForm(){
 const help=helpIndex(catalog.help);if(!catalog.form_layout)throw Error('参数分组定义未加载，请重新加载新版服务。');
 const metaFor=path=>help[path]||help[path.replace(/^targets\./,'system_targets.').replace(/^system\./,'')]||help[path.split('.').pop()];
 const markCondition=(node,condition)=>{if(condition)node.dataset.showWhen=JSON.stringify(condition);};
 const makeField=(definition,section)=>{
  const path=definition.path,kinds=fieldSchema(path).anyOf||[fieldSchema(path)],spec=kinds.find(k=>k.type!=='null'),nullable=kinds.some(k=>k.type==='null'),meta=metaFor(path);
  if(!meta)throw Error('缺少参数说明：'+path);
  const wrap=document.createElement('div');wrap.className='field';if(definition.label)wrap.classList.add('role-labelled-field');wrap.title=meta.description;if(definition.full)wrap.classList.add('field-full');markCondition(wrap,definition.when);
  const label=document.createElement('label');label.htmlFor='f-'+path;const caption=document.createElement('span');caption.className='label-text';caption.textContent=definition.label||meta.label;label.append(caption);
  if(definition.labels_by_shape)caption.dataset.labelsByShape=JSON.stringify(definition.labels_by_shape);
  if(!section.unit&&!spec.enum&&spec.type!=='boolean'){const unit=document.createElement('small');unit.textContent=LidarUnits.unit(path,meta.ui_unit||meta.unit);label.append(' ',unit);}
  const input=document.createElement(spec.enum||spec.type==='boolean'?'select':'input');input.id='f-'+path;Object.assign(input.dataset,{path,kind:spec.type,nullable:String(nullable)});input.setAttribute('aria-label',meta.label);
  if(input.tagName==='SELECT'){for(const value of (path==='transport.payload_format'?spec.enum.filter(v=>v!=='events'):spec.enum)||(spec.type==='boolean'?['true','false']:[])){const o=document.createElement('option');o.value=String(value);o.textContent=enumNames[value]||value;input.append(o);}}
  else{input.type='number';input.step=spec.type==='integer'?'1':'any';input.placeholder=nullable?'自动 / 待提供':'必填';}
  input.addEventListener('input',()=>input.dataset.edited='true');input.addEventListener('change',changed);wrap.append(label,input);
  if(meta.ui_note){const note=document.createElement('small');note.className='field-help';note.textContent=meta.ui_note;wrap.append(note);}
  if(path==='system.rx.rx_efficiency'||path==='system.spad.spad_jitter_fwhm_ps'){const note=document.createElement('small');note.className='field-help';note.textContent=meta.budget_note||meta.description;wrap.append(note);}
  if(['geometry.tx_h_width_mrad','rx_channel.h_width_mrad','rx_channel.v_width_deg'].includes(path)){const note=document.createElement('small');note.className='field-help angle-equivalent';note.dataset.angleNote=path;wrap.append(note);}
  return wrap;
 };
 const makeAngle=(id,caption)=>{const wrap=document.createElement('div');wrap.className='field derived-field';wrap.title=help.tx_channel_v_mrad.description;wrap.innerHTML=`<label for="${id}">${caption} <small>${id==='channelVReadout'?'mrad · ':''}自动</small></label><input id="${id}" aria-label="${caption}（自动计算）" readonly data-focus-path="system.spad.channels_v"><small class="field-help" id="${id}Note">VFOV ÷ 线数 · 等价角度待计算</small>`;return wrap;};
 for(const module of catalog.form_layout){
  const d=document.createElement('details');d.className='parameter-module';d.dataset.module=module.module;d.open=['系统目标','Tx发射','SPAD与读出'].includes(module.module);const sum=document.createElement('summary');sum.textContent=module.module;d.append(sum);
  for(const definition of module.sections){
   const section=document.createElement('section');section.className='parameter-section parameter-card';section.dataset.section=definition.title;markCondition(section,definition.when);
   const header=document.createElement('div');header.className='parameter-card-header';const h=document.createElement('h3');h.textContent=definition.title;header.append(h);if(definition.unit){const unit=document.createElement('small');unit.textContent=definition.unit;header.append(unit);}
   const grid=document.createElement('div');grid.className='field-grid';if(definition.fields.length===1){grid.classList.add('single-field-grid');section.classList.add('single-parameter-card');}
   for(const field of definition.fields)grid.append(makeField(field,definition));section.append(header,grid);
   for(const id of definition.derived||[]){
    if(id==='txVReadout'){grid.append(makeAngle(id,'V 发光全角'));grid.classList.remove('single-field-grid');section.classList.remove('single-parameter-card');}
    else if(id==='channelVReadout'){grid.classList.add('pointcloud-grid');grid.append(makeAngle(id,'单通道 V 全角'));}
    else if(id==='angularSampling'){const box=document.createElement('div');box.id=id;box.className='angular-sampling';box.innerHTML='<span>自动角分辨率 · 采样步距</span><strong id="angularSamplingMrad">计算中</strong><small id="angularSamplingDeg"></small>';section.append(box);}
    else if(['histogramReadout','memoryReadout','fifoReadout','copyRateReadout'].includes(id)){const box=document.createElement('div');box.id=id;box.className='automatic-readouts';const items=id==='histogramReadout'?[['histogramBinCount','直方图bin数量']]:id==='memoryReadout'?[['bankBudget','每芯片单块SRAM'],['chipSramBudget','每芯片SRAM合计']]:id==='fifoReadout'?[['fifoBudget','每link输出FIFO']]:[['copyRateBudget','搬移速率要求']];for(const [key,caption]of items){const wrap=document.createElement('div');wrap.className='field derived-field';wrap.innerHTML=`<label for="${key}">${caption} <small>自动</small></label><input id="${key}" aria-label="${caption}（自动计算）" readonly>`;box.append(wrap);}const note=document.createElement('small');note.id=id+'Note';note.className='field-help';box.append(note);section.append(box);}
    else if(id==='followRxV'){const button=document.createElement('button');button.id=id;button.type='button';button.textContent='Rx V跟随Tx';button.onclick=()=>{const input=$('f-rx_channel.v_width_deg');input.value='';input.dataset.edited='true';changed();};section.append(button);}
    else{const box=document.createElement('div');box.id=id;box.className=id.endsWith('Derived')&&id!=='binningDerived'?'derived-panel':'parameter-derived';box.textContent='派生结果待计算';section.append(box);}
   }
   d.append(section);
  }
  $('fields').append(d);
 }
 for(const [k,meta]of Object.entries(catalog.curves.groups)){const d=document.createElement('details');d.className='parameter-module';const sum=document.createElement('summary');sum.textContent=meta.label;const root=document.createElement('div');root.id='curve-'+k;d.append(sum,root);$('curves').append(d);}editors=new CurveEditors(catalog.curves,changed,(k,s)=>request('/api/curve/validate?kind='+k,s));
}

function fill(c){config=clone(c);for(const e of document.querySelectorAll('[data-path]')){const v=get(c,e.dataset.path);e.value=v===null?'':(e.dataset.kind==='number'||e.dataset.kind==='integer')?BudgetNumbers.input(displayFactors[e.dataset.path]?v*displayFactors[e.dataset.path]:v):String(v);e.dataset.displayOriginal=e.value;e.dataset.edited='false';}editors.fill(c.system.spectral_inputs);visibility();}
function collect(){const c=clone(config);for(const e of document.querySelectorAll('[data-path]')){let v=e.value;if(v===''){if(e.dataset.nullable==='true')v=null;else throw Error(e.getAttribute('aria-label')+'不能为空');}else if(e.dataset.kind==='boolean')v=v==='true';else if(e.dataset.kind==='integer'||e.dataset.kind==='number'){v=Number(v);if(!Number.isFinite(v))throw Error('参数必须为有限数');if(e.dataset.kind==='integer'&&!Number.isInteger(v))throw Error(e.getAttribute('aria-label')+'必须为整数');if(e.value===e.dataset.displayOriginal&&e.dataset.edited!=='true')v=get(config,e.dataset.path);else if(displayFactors[e.dataset.path])v/=displayFactors[e.dataset.path];}put(c,e.dataset.path,v);}c.system.spectral_inputs=editors.values();return c;}
function visibility(){
 for(const node of document.querySelectorAll('#fields [data-show-when]')){const condition=JSON.parse(node.dataset.showWhen),input=$('f-'+condition.path);if(!input)throw Error('条件字段未定义：'+condition.path);node.hidden=!condition.values.includes(input.value);}
 const shape=$('f-system.rx.rx_aperture_shape').value;
 for(const label of document.querySelectorAll('[data-labels-by-shape]')){const values=JSON.parse(label.dataset.labelsByShape);if(values[shape])label.textContent=values[shape];}
}

function save(c){localStorage.setItem(KEY,JSON.stringify({draft:envelope(c),baseline}));}
function changed(){revision++;window.dispatchEvent(new Event('budget-scene-stale'));visibility();$('resultState').textContent='参数已改 · 结果待更新';$('formState').textContent='草稿已修改；下方保留上次有效预算。';$('pin').disabled=true;$('sendB').disabled=true;try{save(collect());}catch(e){fail(e);return;}clearTimeout(timer);timer=setTimeout(calculate,catalog.algorithms.parameter_preview_debounce_ms);}
async function calculate(){if(running){queued=true;return;}clearTimeout(timer);let draft;try{draft=collect();}catch(e){fail(e);return;}const rev=revision,requestedValues=new Map([...document.querySelectorAll('[data-path]')].map(e=>[e.dataset.path,e.value]));running=true;window.dispatchEvent(new Event('budget-scene-stale'));$('calculate').disabled=true;$('pin').disabled=true;$('sendB').disabled=true;$('resultState').textContent='正在计算 · 结果待更新';$('formState').textContent='正在计算静态光学与系统预算…';try{const next=await request('/api/system-budget/calculate',draft);if(rev!==revision){queued=true;return;}result=next;config=clone(next.configuration.experiment);for(const e of document.querySelectorAll('[data-path]')){if((e.dataset.kind==='number'||e.dataset.kind==='integer')&&e.value===requestedValues.get(e.dataset.path)&&document.activeElement!==e){const v=get(config,e.dataset.path);e.value=v===null?'':BudgetNumbers.input(displayFactors[e.dataset.path]?v*displayFactors[e.dataset.path]:v);e.dataset.displayOriginal=e.value;e.dataset.edited='false';}}$('error').hidden=true;$('resultState').textContent='当前参数 · 已计算';$('formState').textContent='计算完成；功率×脉宽换算单发能量，Rx角域独立。';$('pin').disabled=false;$('sendB').disabled=next.b_simulation_runnable===false;$('sendB').title=next.b_simulation_runnable===false?next.b_simulation_blocker:'送入B验证';render();save(config);}catch(e){fail(e);$('resultState').textContent='计算失败 · 保留旧结果';$('formState').textContent='当前参数无有效预算，请修正错误。';$('pin').disabled=true;$('sendB').disabled=true;}finally{running=false;$('calculate').disabled=false;if(queued){queued=false;calculate();}}}
function cards(keys){return keys.map(k=>`<div class="metric"><div class="label">${metricDefs[k][0]}</div><div class="value">${fmt(result.metrics[k])}</div><div class="unit">${metricDefs[k][1]}</div></div>`).join('');}
function facts(keys){return keys.map(k=>`<div class="fact">${metricDefs[k][0]}<strong>${fmt(result.metrics[k])} <small>${metricDefs[k][1]}</small></strong></div>`).join('');}
function latex(el,source){try{katex.render(source,el,{displayMode:true,throwOnError:true});}catch(e){el.textContent='公式渲染失败：'+e.message+'\n'+source;el.dataset.formulaError='true';}}
function formulas(root,items){root.replaceChildren();for(const f of items){const box=document.createElement('div');box.className='formula';if(f.title){const h=document.createElement('h3');h.textContent=f.title;box.append(h);}const math=document.createElement('div');latex(math,f.latex);box.append(math);const p=document.createElement('p');p.className='note';p.textContent=f.note||f.symbols;box.append(p);if(f.values){const table=document.createElement('table');table.innerHTML=f.values.map(v=>`<tr><td>${esc(v.label)}</td><td>${fmt(v.value)}</td><td>${esc(v.unit)}</td></tr>`).join('');box.append(table);}root.append(box);}}
function timeline(){BudgetCharts.timing(result);}
function photonChart(){BudgetCharts.photons(result,formulas);}
function renderPrbs(){const p=result.prbs;if(!p){$('prbs').innerHTML='<p class="note">尚未启用。左侧填写码片数、码片时长及开码片数，可估算独立候选方案的周期、光能与扫描位移。</p>';return;}const fields=[['码周期',p.period_ns,'ns'],['开码片比例',p.on_fraction,'1'],['每码周期能量',p.energy_nj,'nJ'],['码周期平均光功率',p.code_average_power_w,'W'],['名义周期距离',p.nominal_periodic_range_m,'m'],['序列期间扫描位移',p.sweep_mrad,'mrad']];$('prbs').innerHTML='<div class="facts">'+fields.map(([k,v,u])=>`<div class="fact">${k}<strong>${fmt(v)} <small>${u}</small></strong></div>`).join('')+'</div>'+`<p class="note">${esc(p.note)}</p><p class="${p.within_column&&p.pulse_fwhm_within_chip?'note':'orange'}">${p.within_column?'码周期可放入列周期':'码周期超过列周期'}；${p.pulse_fwhm_within_chip?'脉冲FWHM小于码片':'脉冲FWHM不小于码片，短脉冲编码假设不满足'}。</p>`;}
function renderVertical(){const v=result.vertical_budget,m=result.metrics;if(!v)return;const r=v.rows[0];$('verticalNote').textContent='均匀空间模型：'+m.channels+' 个V角通道按相同份额均分功率和能量；每个通道采用同一B光学核心。';$('verticalTx').innerHTML='<table><thead><tr><th>代表通道</th><th>Tx H × V / mrad</th><th>全Tx份额</th><th>等效功率 / W</th><th>单发能量 / nJ</th></tr></thead><tbody><tr><td>任一V通道</td><td>'+fmt(v.tx_h_full_mrad)+' × '+fmt(m.tx_channel_v_mrad)+'</td><td>'+fmt(r.tx_fraction)+'</td><td>'+fmt(m.channel_power_w)+'</td><td>'+fmt(m.channel_energy_nj)+'</td></tr></tbody></table>';$('verticalRx').textContent='Rx单通道 H '+fmt(m.rx_channel_h_mrad)+' × V '+fmt(m.rx_channel_v_mrad)+' mrad；候选光子与时间窗见上方单通道预算。完整角边界与逐通道数组仍可从审计快照导出。';}
function flatten(o,p='',out={}){for(const [k,v]of Object.entries(o)){const path=p?p+'.'+k:k;if(v!==null&&typeof v==='object'&&!Array.isArray(v))flatten(v,path,out);else out[path]=JSON.stringify(v);}return out;}
function displayDiff(raw){try{const v=JSON.parse(raw);return typeof v==='number'?fmt(v):raw;}catch{return raw;}}
function compare(){if(!baseline){$('comparison').innerHTML='';$('differences').innerHTML='';$('baselineNote').textContent='点击“保存为对比基准”，再修改参数查看变化。';return;}$('baselineNote').textContent=`${baseline.configuration.experiment.rx_channel?'':'旧版全阵列口径，不能直接对照当前独立角通道性能。'}基准为保存时的计算快照（${baseline.provenance.utc}，版本 ${baseline.provenance.model_version}，指纹 ${baseline.provenance.configuration_sha256.slice(0,12)}）；刷新不会改写基准。`;$('comparison').innerHTML='<table><thead><tr><th>指标</th><th>基准</th><th>当前方案</th><th>单位</th></tr></thead><tbody>'+Object.entries(metricDefs).map(([k,[label,unit]])=>`<tr><td>${label}</td><td>${fmt(baseline.metrics[k])}</td><td class="${baseline.metrics[k]!==result.metrics[k]?'changed':''}">${fmt(result.metrics[k])}</td><td>${unit}</td></tr>`).join('')+'</tbody></table>';const a=flatten(baseline.configuration.experiment),b=flatten(result.configuration.experiment);const diffs=[...new Set([...Object.keys(a),...Object.keys(b)])].filter(k=>a[k]!==b[k]);$('differences').innerHTML=diffs.length?'<table><tr><th>参数路径</th><th>基准</th><th>当前</th></tr>'+diffs.map(k=>`<tr><td>${esc(k)}</td><td>${esc(displayDiff(a[k]))}</td><td>${esc(displayDiff(b[k]))}</td></tr>`).join('')+'</table>':'<p class="note">输入一致。</p>';}
function renderParameterDerived(){
 $('binningDerived').textContent='自动：'+fmt(result.metrics.spads_per_channel)+' cells / 角通道 · 整阵列 '+fmt(result.metrics.physical_spads)+' cells';
 const d=result.schematic.views.detector_view;
 $('binningSize').textContent=d?'完整探测尺寸：H '+fmt(d.detector_h_um)+' × V '+fmt(d.detector_v_um)+' μm':'尺寸数据待加载';
}
function renderAutomaticBudgets(){
 const h=result.electrical.histogram,s=result.electrical.selected,m=s.memory;
 $('histogramBinCount').value=fmt(h.bin_count)+' bin';
 $('histogramReadoutNote').textContent='窗口 '+fmt(h.gate_width_ns)+' ns · 单bin '+fmt(h.bin_width_ns)+' ns · bin数量自动向上取整';
 $('bankBudget').value=m?memorySize(m.maximum_bank_bytes):'待计算';
 $('chipSramBudget').value=m?memorySize(m.maximum_chip_sram_bytes):'待计算';
 $('memoryReadoutNote').textContent=m?'每chip '+m.banks_per_chip+' 块 · 全系统SRAM '+memorySize(m.total_sram_bytes)+' · 不含DSP工作区':'字宽/输出格式完整后计算缓存预算';
 $('fifoBudget').value=m?memorySize(m.maximum_fifo_bytes):'待计算';
 $('copyRateBudget').value=result.configuration.experiment.electrical.buffer_architecture==='single'?'旁路':s.copy_required_mbps==null?fmt(null):s.copy_required_mbps>=1000?fmt(s.copy_required_mbps/1000)+' Gbit/s':fmt(s.copy_required_mbps)+' Mbit/s';
 $('copyRateReadoutNote').textContent=result.configuration.experiment.electrical.buffer_architecture==='single'?'单缓冲旁路A→B搬移':'按当前每chip整slot Hist数据量与所填时间反推，不是实际器件规格';
 $('fifoReadoutNote').textContent=m?'有限FIFO按 '+m.fifo_columns+' 列完整数据预算，满时背压；实际占用峰值见电学结果':'输出记录完整后计算FIFO预算';
}
function render(){renderParameterDerived();renderAutomaticBudgets();$('angularSamplingMrad').textContent='H '+fmt(result.metrics.horizontal_angle_step_mrad)+' × V '+fmt(result.metrics.tx_channel_v_mrad)+' mrad';$('angularSamplingDeg').textContent='等价 H '+fmt(result.metrics.angle_step_deg)+' × V '+fmt(result.metrics.vertical_angle_step_deg)+' deg';for(const e of document.querySelectorAll('[data-angle-note]')){const key=({'geometry.tx_h_width_mrad':'tx_channel_h_deg','rx_channel.h_width_mrad':'rx_channel_h_deg','rx_channel.v_width_deg':'rx_channel_v_deg'})[e.dataset.angleNote];e.textContent='等价 '+fmt(result.metrics[key])+' deg';}for(const id of ['txVReadout','channelVReadout']){$(id).value=fmt(result.metrics.tx_channel_v_mrad);$(id+'Note').textContent='等价 '+fmt(result.metrics.tx_channel_v_deg)+' deg';}for(const d of document.querySelectorAll('#fields .parameter-module')){let brief=d.querySelector(':scope>summary small');if(!brief){brief=document.createElement('small');d.querySelector(':scope>summary').append(brief);}brief.textContent=({'系统目标':result.metrics.channels+'线 · '+fmt(result.metrics.vfov_deg)+'° VFOV','Tx发射':'单通道 H '+fmt(result.configuration.experiment.geometry.tx_h_width_mrad)+' × V '+fmt(result.metrics.tx_channel_v_mrad)+' mrad','Rx接收':'单通道 H '+fmt(result.metrics.rx_channel_h_mrad)+' × V '+fmt(result.metrics.rx_channel_v_mrad)+' mrad\n入瞳 '+(result.configuration.experiment.system.rx.rx_aperture_shape==='circle'?'D '+fmt(result.configuration.experiment.system.rx.rx_aperture_mm):fmt(result.configuration.experiment.system.rx.rx_aperture_width_mm)+' × '+fmt(result.configuration.experiment.system.rx.rx_aperture_height_mm))+' mm · f '+fmt(result.configuration.experiment.system.rx.focal_length_h_mm)+' × '+fmt(result.configuration.experiment.system.rx.focal_length_v_mm)+' mm','SPAD与读出':'通道 H 1 × V '+result.metrics.channels+'\nSPAD/通道 H '+result.configuration.experiment.system.spad.H_binning+' × V '+result.configuration.experiment.system.spad.V_binning+'\nHist '+fmt(result.metrics.histogram_bins)+' bin · '+fmt(result.configuration.experiment.system.acquisition.gate_width_ns)+' ns'})[d.dataset.module]||'';}$('channelDerived').innerHTML='<small>自动计算 · 空间均匀 / H方向一路</small>'+facts(['channel_power_w','channel_energy_nj','tx_channel_v_mrad']);$('rxDerived').textContent='实际收光：H '+fmt(result.metrics.rx_channel_h_mrad)+' × V '+fmt(result.metrics.rx_channel_v_mrad)+' mrad';window.budgetScenePayload={schematic:result.schematic,mappingMode:result.configuration.experiment.system.rx.mapping_mode,fingerprint:result.provenance.configuration_sha256};window.dispatchEvent(new CustomEvent('budget-scene-update',{detail:window.budgetScenePayload}));$('metrics').innerHTML=cards(['pulse_average_power_w','single_pulse_energy_nj','column_time_us','time_margin_us','column_energy_nj','average_optical_power_w','vfov_deg','tx_channel_v_mrad']);$('timeFacts').innerHTML=facts(['acquisition_envelope_us','margin_without_reset_us','max_pulses_per_column','max_frame_rate_hz','angle_step_deg','required_optical_rad_s','pulse_train_sweep_mrad','return_rotation_mrad','gate_fraction']);$('resourceFacts').innerHTML=facts(['peak_optical_power_w','average_output_power_w','electric_power_w','emitter_heat_w','channels','spads_per_channel','physical_spads','histogram_bins','histogram_body_bytes','histogram_payload_bytes','average_payload_mbps','wire_time_us','final_mixed_records']);$('constraints').innerHTML=result.constraints.map(c=>`<div class="check"><span class="state ${c.status}">${({pass:'满足',fail:'超限',unknown:'待确认',review:'需验证'})[c.status]}</span><strong>${esc(c.label)}</strong><p>${esc(c.detail)}</p></div>`).join('');$('stamp').textContent=`${result.provenance.utc.replace(/\.\d+(?=[+Z])/,'')} · 模型 ${result.provenance.model_version} · 配置 ${result.provenance.configuration_sha256.slice(0,16)} · 当前构造光学默认不代表实物`;timeline();photonChart();BudgetHardwareViews.render(result);renderVertical();renderPrbs();compare();formulas($('formulaList'),result.formulas);$('limitations').innerHTML=result.limitations.map(s=>`<li>${esc(s)}</li>`).join('');$('audit').textContent=JSON.stringify({provenance:result.provenance,configuration:result.configuration},null,2);}
async function init(){catalog=await request('/api/system-budget');buildForm();let initial=catalog.defaults;const saved=localStorage.getItem(KEY);let cacheError=null;if(saved){try{const state=JSON.parse(saved);if(state.draft.schema_version<7)localStorage.setItem(KEY+'-before-v7',saved);if(state.draft.schema_version<6)localStorage.setItem(KEY+'-before-v6',saved);if(state.draft.schema_version<5)localStorage.setItem(KEY+'-before-v5',saved);if(state.draft.schema_version<4)localStorage.setItem(KEY+'-before-v4',saved);if(state.draft.schema_version<3)localStorage.setItem(KEY+'-before-v3',saved);initial=await request('/api/system-budget/import',JSON.stringify(state.draft),true);if(state.baseline){if(!state.baseline.metrics||!state.baseline.provenance||!state.baseline.configuration)throw Error('基准快照结构不完整');baseline=state.baseline;}}catch(e){localStorage.setItem(KEY+'-rejected',saved);cacheError=new Error('旧草稿无法加载，原内容已保留在恢复副本中；本页使用当前默认值。\n'+e.message);}}fill(initial);await calculate();if(saved&&!cacheError&&JSON.parse(saved).draft.schema_version<7)$('formState').textContent='旧草稿已备份并迁移至v7：Hist搬移改用时间输入，原速率按当前数据量转换为等效时间；其他工况保留。';if(cacheError)fail(cacheError);}
$('calculate').onclick=calculate;
$('pin').onclick=()=>{if(!result||running)return;baseline=clone(result);save(collect());compare();};
$('clearBaseline').onclick=()=>{baseline=null;save(collect());compare();};
$('reset').onclick=async()=>{try{catalog=await request('/api/system-budget');fill(catalog.defaults);revision++;await calculate();}catch(e){fail(e);}};
$('loadJson').onclick=()=>{try{$('configJson').value=JSON.stringify(collect(),null,2);}catch(e){fail(e);}};
$('applyJson').onclick=async()=>{try{const c=await request('/api/system-budget/import',JSON.stringify(envelope(JSON.parse($('configJson').value))),true);fill(c);revision++;await calculate();}catch(e){fail(e);}};
$('exportConfig').onclick=()=>{try{download('hardware-budget-config.json',envelope(collect()));}catch(e){fail(e);}};
$('exportResult').onclick=()=>{if(result)download('hardware-budget-snapshot.json',{...result,comparison_baseline:baseline});};
$('importConfig').onchange=async e=>{try{const c=await request('/api/system-budget/import',await e.target.files[0].text(),true);fill(c);revision++;await calculate();}catch(err){fail(err);}finally{e.target.value='';}};
$('sendB').onclick=()=>{if(!result)return;sessionStorage.setItem('lidar-budget-to-system',JSON.stringify({experiment:result.configuration.experiment.system}));location.href='/system';};
init().catch(fail);

window.budgetExtensions={request,collect,fill,calculate,catalog:()=>catalog,changed};
$('collapseAll').onclick=()=>document.querySelectorAll('.controls details').forEach(d=>d.open=false);$('expandAll').onclick=()=>document.querySelectorAll('.controls details').forEach(d=>d.open=true);

