668);padding:3px 7px;border-radius:4px;display:inline-block;margin:8px 0}.histogram-plots .exposure-timeline{height:138px;margin-top:8px}.exposure-timeline-label{display:flex;justify-content:space-between;gap:10px;font-size:9px;color:var(--theme-ink-84a8ba, #84a8ba);border-top:1px solid var(--line);padding-top:11px;margin-top:11px}.exposure-timeline-label>span:last-child{color:var(--theme-ink-62d4c3, #62d4c3)}.hist-loading{grid-column:1/-1;color:var(--muted);font-size:12px;padding:26px;border:1px dashed var(--line);border-radius:8px}.bh-reference-note{font-size:10px;line-height:1.7;color:var(--muted);margin-top:9px}.b-gate-example{margin:11px 0;padding:12px;background:var(--theme-color-181f35, #181f35);border:1px solid var(--theme-color-3b4464, #3b4464);border-radius:6px;color:var(--theme-ink-bfc5e3, #bfc5e3);font-size:11px}.b-gate-example strong{color:var(--theme-ink-d2cafa, #d2cafa)}.scope-small{color:var(--theme-ink-6ecdc8, #6ecdc8);font:9px var(--mono)}
