.lab-layout{grid-template-columns:420px minmax(0,1fr)}.lab-results{display:grid;gap:20px;align-content:start}.lab-card{padding:22px}.card-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.muted{color:var(--muted);font-size:13px;line-height:1.7}.lab-error{background:var(--theme-color-422027, #422027);border:1px solid var(--red);padding:16px;border-radius:10px;white-space:pre-wrap;overflow-wrap:anywhere}.lab-card pre{max-height:500px;overflow:auto;font:12px/1.7 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.job{display:flex;align-items:center;gap:12px;border-top:1px solid var(--line);padding:12px 0;flex-wrap:wrap}.job .job-info{flex:1;min-width:170px}.job small{display:block;color:var(--muted)}.job progress{width:100%;height:5px;accent-color:var(--cyan)}.chart-grid{display:grid;grid-template-columns:1fr;gap:24px;margin:22px 0}.chart-grid canvas{width:100%;height:260px;background:var(--bg);border-radius:8px}.chart-grid h3{font-size:14px;color:var(--muted);font-weight:500}.metric-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:18px}.metric{padding:12px;background:var(--panel-2);border-radius:8px;min-width:0}.metric small{color:var(--muted);display:block}.metric strong{font:24px/1.8 Consolas,monospace;color:var(--cyan);overflow-wrap:anywhere}.file-button{cursor:pointer;padding:8px;border:1px solid var(--line);border-radius:7px;font-size:12px}.file-button input{display:none}.controls .toolbar{margin-bottom:12px;flex-wrap:wrap}#formStatus{font-size:12px;color:var(--muted);line-height:1.6}nav.toolbar{flex-wrap:wrap}.controls textarea{width:100%;background:var(--bg);color:var(--text);border:1px solid var(--line);padding:8px}.lab-card .toolbar{align-items:end;flex-wrap:wrap}.lab-card .toolbar input{display:block;background:var(--bg);color:var(--text);border:1px solid var(--line);padding:8px}.lab-card table{width:100%;font-size:12px;border-collapse:collapse}.lab-card td,.lab-card th{padding:8px;text-align:right;border-bottom:1px solid var(--line)}.synthetic-note{padding:12px;border:1px solid var(--orange);color:var(--orange);border-radius:8px;margin-bottom:12px}.hidden{display:none!important}@media(max-width:1000px){.lab-layout{grid-template-columns:1fr}.controls{position:static;max-height:none}.metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}header{align-items:start;gap:15px;flex-direction:column}}@media(min-width:1400px){.chart-grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){main{padding:16px}header{padding:20px 16px}.lab-card{padding:15px}}

