.lab-layout>*{min-width:0}.lab-card{min-width:0}.controls .field-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.controls label{min-width:0}.controls input,.controls select,.lab-card select{min-width:0;max-width:100%}.lab-card td,.lab-card th{white-space:normal;overflow-wrap:anywhere}.formula{max-width:100%;overflow-x:auto}@media(max-width:1000px){.lab-layout{grid-template-columns:minmax(0,1fr)}}
.scan-toolbar{margin-top:18px;gap:12px}.scan-table{max-width:100%;overflow:auto;max-height:440px}.scan-table table{min-width:850px}.scan-wide-plot{width:100%;height:220px;background:var(--bg);border-radius:8px}#scanPanel h3{font-size:14px;color:var(--muted)}#scanNotes{margin-top:16px}#scanPanel{min-width:0}.scan-toolbar input{max-width:170px}.scan-toolbar label{max-width:100%}

