 $('statisticsNote').textContent='单次扫描的分角观测；不从一份观测推造重复统计。';$('replayBin').value=s.processing_bin_ps;$('binNote').textContent='显示分箱 '+s.processing_bin_ps+' ps · 原始 TDC '+data.record_schema.tdc_bin_ps+' ps';}
function chooseScanBin(){if(!scanView)return;const previousFrame=scanFrameIndex;scanFrameIndex=+$('scanFrameSelect').value;scanAngleIndex=+$('scanAngleSelect').value;if(previousFrame!==scanFrameIndex&&scanView.histogram_cube_counts)$('scanPulseIndex').value=scanView.schedule.find(r=>r.frame===scanFrameIndex)?.cycle??'';scanPageIndex=0;if(scanView.histogram_cube_counts){data={...data,histogram:{edges_ns:scanView.histogram_edges_ns,time_ns:scanView.histogram_time_ns,counts:scanView.histogram_cube_counts[scanFrameIndex][scanAngleIndex],bin_ps:scanView.processing_bin_ps},references:null,statistics:null};renderHistograms();updateScanHistogramScope();}drawScanResults();drawScanSchedule();}
async function replayScanWorkspace(){try{$('replayRecords').disabled=true;const rebuilt=await request('/api/jobs/'+displayedJob+'/scan-replay',{bin_ps:$('replayBin').valueAsNumber});scanView={...scanView,...rebuilt};data.scan=scanView;chooseScanBin();$('replayState').textContent='同一记录按新时间分箱重建距离和点云；未重新采样。';}catch(error){setError(error);}finally{$('replayRecords').disabled=false;}}
function bindScanWorkspace(){
 $('toScan').onclick=()=>location.href='/system';$('scanQuickDemo').onclick=async()=>{try{await importForm(await request('/api/experiments/scan/demo'));toast('已载入具名快速示例：默认扫描参数，关闭太阳和其他环境光。');}catch(error){setError(error);}};
 $('scanRefreshPreview').onclick=async()=>{try{await refreshPreview();showModel(previewData,false);}catch(error){setError(error);}};$('scanShowAcquisition').onclick=()=>{if(lastResult)showModel(lastResult,true);};$('scanFrameSelect').onchange=$('scanAngleSelect').onchange=chooseScanBin;
 $('scanBinPicker').onclick=e=>{const button=e.target.closest('[data-scan-bin]');if(button){$('scanAngleSelect').value=button.dataset.scanBin;chooseScanBin();}};
 $('scanRangeLayout').onchange=$('scanCloudProjection').onchange=$('scanShowTruth').onchange=$('scanSharedAxes').onchange=drawScanResults;
 $('scanPreviousPage').onclick=()=>{scanPageIndex--;drawScanSchedule();};$('scanNextPage').onclick=()=>{scanPageIndex++;drawScanSchedule();};
 $('scanExportCloud').onclick=()=>{const link=document.createElement('a');link.href='/api/jobs/'+displayedJob+'/point-cloud.csv?bin_ps='+encodeURIComponent(scanView.processing_bin_ps);link.download=displayedJob+'-point-cloud.csv';link.click();};
 $('scanShowPulse').onclick=()=>{try{const cycle=$('scanPulseIndex').valueAsNumber,pulse=scanView.signal_components.find(p=>p.cycle===cycle);if(!pulse)throw Error('该参考时隙不存在。');heatmap('sensorPlot',reshape(pulse.signal_photons_per_pixel,data.optics.array_shape),data.x_edges_um,data.y_edges_um,{xLabel:'x · μm',yLabel:'y · μm',colorLabel:'光子/发',pixel:true,groups:$('showGroups').checked});$('spatialViewState').textContent='参考时隙 '+cycle+' · 探测面入射期望 · PDE / FF 前';const row=scanView.schedule.find(r=>r.cycle===cycle);$('scanPulseNote').textContent='时隙 '+cycle+' · 帧 '+row.frame+' · 分配 bin '+row.assigned_bin+' · '+(row.emitted?'发射开启':'发射关闭')+'；未改变采集记录。';$('sensorPlot').scrollIntoView({block:'center',behavior:'smooth'});}catch(error){setError(error);}};
 $('scanShowMean').onclick=()=>{renderSpatial();$('spatialViewState').textContent='启用发射时隙的平均探测面入射期望 · PDE / FF 前';$('scanPulseNote').textContent='已恢复完整采集的平均像面。';};
 $('exportHistogram').onclick=()=>{let csv='frame,angle_bin,channel,time_ns,observed_counts,processing_bin_ps\n';for(const ch of selectedChannels)data.histogram.time_ns.forEach((t,i)=>csv+=[scanFrameIndex,scanAngleIndex,ch,t,data.histogram.counts[ch][i],data.histogram.bin_ps].join(',')+'\n');download('c-selected-histograms.csv',csv);};
}

