/* Display-only SI conversion. Stored configurations always retain canonical cps. */
(function(){
 'use strict';
 const isDcr=path=>path.split('.').at(-1)==='dcr_cps_per_spad';
 const factor=path=>isDcr(path)?1/1000:1;
 globalThis.LidarUnits={
  displayFactor:factor,
  display:(value,path)=>typeof value==='number'?value*factor(path):value,
  canonical:(value,path)=>{if(typeof value!=='number')return value;const result=value/factor(path);if(!Number.isFinite(result)&&isDcr(path))throw Error(path+'需要有限数值');return result;},
  unit:(path,unit)=>isDcr(path)?'kHz':unit
 };
})();

web/styles.css.text:
:root {
  --bg: var(--theme-color-0b0f14, #0b0f14);
  --panel: var(--theme-color-121923, #121923);
  --panel-2: var(--theme-color-17212e, #17212e);
  --line: var(--theme-color-263547, #263547);
  --text: var(--theme-color-edf4fa, #edf4fa);
  --muted: var(--theme-color-8da0b3, #8da0b3);
  --cyan: var(--theme-color-41d9d0, #41d9d0);
  --cyan-soft: var(--theme-color-153f43, #153f43);
  --orange: var(--theme-color-ffb55b, #ffb55b);
  --red: var(--theme-color-ff6f77, #ff6f77);
  --blue: var(--theme-color-659cff, #659cff);
}

* { box-sizing: border-box; }
body {
  margin: 0;
  color: var(--text);
  background:
    radial-gradient(circle at 85% -10%, var(--theme-rgba-41d9d01f, rgba(65,217,208,.12)), transparent 32rem),
    linear-gradient(180deg, var(--theme-color-0b1017, #0b1017), var(--bg));
  font-family: Inter, "Segoe UI", "Microsoft YaHei", sans-serif;
  min-height: 100vh;
}

header {
  max-width: 1600px;
  margin: auto;
  padding: 28px 32px 22px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  border-bottom: 1px solid var(--line);
}
h1 { margin: 4px 0 6px; font-size: clamp(25px, 3vw, 40px); letter-spacing: -.03em; }
h2 { margin: 0 0 4px; font-size: 17px; }
p { margin: 0; }
.eyebrow { color: var(--cyan); letter-spacing: .14em; font: 600 11px/1.4 ui-monospace, monospace; }
.lede, .chart-card p { color: var(--muted); font-size: 13px; }
.status { color: var(--muted); font-size: 12px; border: 1px solid var(--line); padding: 8px 11px; border-radius: 99px; }
.status span { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); margin-right: 7px; }

main { max-width: 1600px; margin: 0 auto; padding: 24px 32px 50px; display: grid; grid-template-columns: 420px 1fr; gap: 22px; }
.panel { background: var(--theme-rgba-121923f0, rgba(18,25,35,.94)); border: 1px solid var(--line); border-radius: 12px; box-shadow: 0 18px 50px var(--theme-rgba-00000026, rgba(0,0,0,.15)); }
.controls { padding: 16px; align-self: start; position: sticky; top: 12px; max-height: calc(100vh - 24px); overflow: auto; }
.toolbar { display: flex; gap: 8px; }
.section-actions { margin-top:8px; }
.sweep-controls { flex-wrap:wrap; align-items:end; margin:12px 0; }
.sweep-controls input { display:block; min-width:240px; background:var(--bg); color:var(--text); border:1px solid var(--line); padding:8px; }
#performanceRows td { white-space:nowrap; }
.section-actions button { flex:1; font-size:12px; padding:7px 10px; }
button { background: var(--panel-2); color: var(--text); border: 1px solid var(--theme-color-314257, #314257); border-radius: 7px; padding: 9px 13px; cursor: pointer; font-weight: 600; }
button:hover { border-color: var(--cyan); }
button.primary { flex: 1; color: var(--theme-ink-061414, #061414); background: var(--cyan); border-color: var(--cyan); }
button:disabled { opacity: .35; cursor: not-allowed; }

details { border-top: 1px solid var(--line); margin-top: 14px; padding-top: 12px; }
summary { cursor: pointer; font-size: 14px; font-weight: 700; color: var(--theme-ink-d7e4ee, #d7e4ee); margin-bottom: 12px; }
.controls > details > summary { color: var(--cyan); }
.controls > details > summary::marker { color: var(--cyan); }
.field-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
label { color: var(--muted); font-size: 11px; line-height: 1.3; }
label.wide { grid-column: span 2; }
input[type="number"], input[type="file"] { width: 100%; margin-top: 4px; color: var(--text); background: var(--theme-color-0b121a, #0b121a); border: 1px solid var(--theme-color-29394c, #29394c); border-radius: 6px; padding: 8px; outline: none; }
input:focus { border-color: var(--cyan); box-shadow: 0 0 0 2px var(--theme-rgba-41d9d014, rgba(65,217,208,.08)); }
label.file { padding: 9px; border: 1px dashed var(--theme-color-34485e, #34485e); border-radius: 7px; }
label.file small { display: block; margin-top: 4px; color: var(--theme-ink-6f8499, #6f8499); }
.footer-tools { margin-top: 14px; border-top: 1px solid var(--line); padding-top: 14px; }

.results { min-width: 0; }
.metric-grid { display: grid; grid-template-columns: repeat(4, minmax(130px, 1fr)); gap: 10px; margin-bottom: 12px; }
.metric-grid article { min-height: 102px; background: linear-gradient(145deg, var(--panel-2), var(--panel)); border: 1px solid var(--line); border-radius: 10px; padding: 14px; }
.metric-grid span, .metric-grid small { display: block; color: var(--muted); font-size: 11px; }
.metric-grid strong { display: inline-block; margin: 10px 6px 2px 0; color: var(--cyan); font: 650 24px/1 ui-monospace, Consolas, monospace; }
.chart-card { padding: 18px; margin-bottom: 12px; }
.chart-card canvas { width: 100%; display: block; margin-top: 14px; background: var(--theme-color-0d141d, #0d141d); border: 1px solid var(--theme-color-1e2a39, #1e2a39); border-radius: 7px; }
.split { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.assumptions { padding: 18px; color: var(--muted); font-size: 13px; }
.assumptions ul { margin-bottom: 12px; padding-left: 21px; }
.assumptions li { margin: 5px 0; }
.warning { color: var(--orange); border-left: 2px solid var(--orange); padding-left: 10px; }
.note { margin-top: 10px !important; color: var(--cyan) !important; }
.error { margin-bottom: 12px; background: var(--theme-rgba-ff6f771f, rgba(255,111,119,.12)); border: 1px solid var(--theme-rgba-ff6f778c, rgba(255,111,119,.55)); color: var(--theme-ink-ffc4c8, #ffc4c8); border-radius: 8px; padding: 12px; white-space: pre-wrap; font-size: 13px; }
.hidden { display: none; }

@media (max-width: 1100px) {
  main { grid-template-columns: 1fr; }
  .controls { position: static; max-height: none; }
}
@media (max-width: 760px) {
  header, main { padding-left: 15px; padding-right: 15px; }
  header { align-items: flex-start; gap: 14px; flex-direction: column; }
  .metric-grid { grid-template-columns: 1fr 1fr; }
  .split { grid-template-columns: 1fr; }
}

select { width:100%; margin-top:4px; padding:8px; color:var(--text); background:var(--theme-color-0b121a, #0b121a); border:1px solid var(--theme-color-29394c, #29394c); border-radius:6px; }
.wide { grid-column:span 2; }
.derived-box { padding:10px; border:1px solid var(--theme-color-285b5b, #285b5b); border-radius:7px; line-height:1.9; font-size:12px; color:var(--muted); }
.derived-box strong { color:var(--cyan); font-family:Consolas,monospace; }
.derived-box small { display:block; line-height:1.5; }
a { color:var(--cyan); }
.toolbar { flex-wrap:wrap; align-items:center; }
.import-config { border:1px solid var(--line); padding:8px; border-radius:7px; cursor:pointer; }
.import-config input { display:block; max-width:175px; margin-top:5px; }
.result-status { color:var(--orange); font-size:12px; margin-bottom:12px; }
.table-scroll { overflow:auto; max-height:600px; margin-top:12px; }
.histogram-methods { margin:12px 0 18px; }
.histogram-methods .table-wrap { overflow-x:auto; }
.histogram-methods table { min-width:570px; table-layout:fixed; line-height:1.6; }
.histogram-methods th:first-child { width:110px; }
.histogram-methods th:nth-child(2) { width:52%; }
.histogram-methods th { position:static; }
table { border-collapse:collapse; font-size:12px; width:100%; }
td, th { border-bottom:1px solid var(--line); padding:9px; text-align:left; vertical-align:top; }
th { position:sticky; top:0; background:var(--panel-2); }
td { overflow-wrap:anywhere; }
pre { white-space:pre-wrap; overflow-wrap:anywhere; color:var(--theme-ink-c6dce7, #c6dce7); font-size:12px; line-height:1.7; }
#debugPanel details { padding-bottom:12px; }
#debugPanel p { line-height:1.7; }
input[readonly] { opacity:.55; }
.hidden { display:none !important; }
body[data-mode="evaluation"] .split { grid-template-columns:1fr; }
textarea { display:block; width:100%; margin-top:6px; padding:9px; box-sizing:border-box; resize:vertical; color:var(--text); background:var(--theme-color-0b121a, #0b121a); border:1px solid var(--line); border-radius:6px; font-family:Consolas,monospace; }
.editor-note, #filterDraftStatus { color:var(--muted); font-size:11px; line-height:1.6; margin:8px 0; display:block; }
.inactive { opacity:.45; }
.formula { overflow-x:auto; padding:10px 0; font-size:14px; }
input[type=checkbox] { accent-color:var(--cyan); }
.curve-editor { border:1px solid var(--line); border-radius:8px; padding:12px; min-width:0; }
.curve-editor > div, .curve-editor > label { margin-top:10px; display:block; }
.curve-editor input[type=file] { max-width:100%; font-size:11px; }
.csv-preview { max-height:160px; overflow:auto; }
.formula-note { font-size:11px !important; line-height:1.75; color:var(--theme-ink-a4b6c8, #a4b6c8) !important; margin:4px 0 12px; overflow-wrap:anywhere; }
.photon-tabs { margin:18px 0; }
.photon-tabs button[aria-pressed=true] { border-color:var(--cyan); background:var(--cyan-soft); }
.photon-step { border-top:1px solid var(--line); padding:14px 0; }
.photon-step h3 { font-size:15px; margin:0 0 8px; }
.photon-logic { line-height:1.7; }
.photon-stamp { color:var(--orange) !important; font-size:12px; margin:8px 0 !important; }
#photonBudgetPanel .table-scroll { max-height:none; }
#photonBudgetPanel th { position:static; }
#photonBudgetPanel td:nth-child(2) { font-family:Consolas,monospace; color:var(--cyan); }

/* Collapsible section titles should remain easy to discover. */
details>summary{font-weight:700}.subdetails>summary,.explanation>summary,.wave-detail>summary{font-weight:700}

/* A evaluation/debug share explicit CSS heights, independent of canvas bitmap size. */
#histZoom { height: 360px; }
#histFull { height: 90px; }
.a-histogram-legend { display: flex; flex-wrap: wrap; gap: 10px 20px; margin: 16px 0; color: var(--muted); font-size: 12px; }
.a-histogram-legend span { display: inline-flex; align-items: center; gap: 7px; }
.a-histogram-legend i { display: inline-block; width: 18px; height: 9px; }
.hist-observed { background: var(--theme-color-5e91dc, #5e91dc); }
.hist-ideal-line { border-top: 2px dashed var(--theme-color-57d8ca, #57d8ca); transform: translateY(4px); }
.a-histogram-legend .hist-ideal-point { width: 6px; height: 6px; border-radius: 50%; background: var(--theme-color-65ecda, #65ecda); }
.hist-noise { border-top: 2px solid var(--theme-color-dba768, #dba768); transform: translateY(4px); }
.hist-error { border-left: 1px solid var(--theme-color-aacbf599, #aacbf599); border-right: 1px solid var(--theme-color-aacbf599, #aacbf599); }
.a-histogram-controls { display: flex; flex-wrap: wrap; align-items: end; gap: 10px; }
.a-histogram-controls label { width: 150px; max-width: 100%; }
.a-histogram-controls button { min-height: 36px; }
@media(max-width:570px) { #histZoom { height:300px; } }

