.scan-workspace{display:flex;flex-direction:column;gap:16px}.scan-preset-actions{margin-top:10px;border-top:1px solid var(--theme-color-28404d, #28404d);padding-top:10px;display:flex;align-items:center;gap:10px}.scan-preset-actions>span{font-size:9px;color:var(--theme-ink-7e9caf, #7e9caf);line-height:1.5}.scan-selectors{display:flex;align-items:end;gap:14px;flex-wrap:wrap;margin:17px 0}.scan-selectors>label{font-size:10px;color:var(--theme-ink-a8bfd0, #a8bfd0);display:flex;flex-direction:column;gap:6px}.scan-selectors select,.scan-selectors input{width:auto;max-width:230px;min-width:100px;padding:7px}.scan-selectors .inline-check{display:flex;flex-direction:row;gap:7px;padding-bottom:7px}.scan-selectors .inline-check input{min-width:0;width:13px}.scan-resource{padding:10px 12px;border:1px solid var(--theme-color-254249, #254249);border-radius:6px;font-size:10px;line-height:1.7;color:var(--theme-ink-94b6bb, #94b6bb);margin-bottom:15px}.scan-resource.over-limit{border-color:var(--theme-color-7b5932, #7b5932);color:var(--theme-ink-edc68e, #edc68e);background:var(--theme-color-2b241b, #2b241b)}.scan-kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}.scan-kpis .metric{padding:10px}.scan-kpis .metric-number{font-size:21px}.scan-plot-grid{display:grid;grid-template-columns:1fr 1fr;gap:23px}.scan-plot-grid>article{min-width:0}.scan-workspace canvas{display:block;width:100%;height:235px;background:var(--theme-color-0b1722, #0b1722);border:1px solid var(--theme-color-243b4d, #243b4d);border-radius:7px}.scan-bin-title{margin-top:22px}.scan-bin-picker{display:flex;gap:4px;overflow:auto;padding:2px 2px 8px}.scan-bin-picker button{min-width:45px;flex:1;display:flex;flex-direction:column;align-items:center;gap:5px;padding:7px 3px;background:linear-gradient(0deg,var(--theme-color-132533, #132533),var(--bin-fill));border:1px solid var(--theme-color-365061, #365061);color:var(--theme-ink-ffffff, white);text-shadow:0 1px 3px var(--theme-color-000000, #000)}.scan-bin-picker button.selected{outline:2px solid var(--theme-color-edb777, #edb777);outline-offset:0}.scan-bin-picker span{font-size:9px}.scan-bin-picker strong{font:16px var(--mono)}.scan-bin-picker small{font:8px var(--mono)}.scan-table-actions{display:flex;justify-content:space-between;margin:10px 0}.scan-range-plots{display:grid;gap:18px;margin:16px 0}.scan-range-plots.multi{grid-template-columns:repeat(2,minmax(0,1fr))}.scan-range-plots>article{min-width:0}.scan-cloud{margin-top:20px}.scan-cloud canvas{height:300px}.scan-hist-scope{font-size:11px;color:var(--theme-ink-b1c8d8, #b1c8d8);margin:0 0 17px;line-height:1.8}.scan-workspace .range-table{white-space:nowrap}
@media(max-width:1150px){.scan-kpis{grid-template-columns:repeat(3,minmax(0,1fr))}.scan-plot-grid{grid-template-columns:1fr}.scan-range-plots.multi{grid-template-columns:1fr}}
@media(max-width:570px){.scan-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.scan-selectors{gap:10px}.scan-selectors>label{max-width:100%}.scan-selectors select{max-width:220px}.scan-preset-actions{align-items:flex-start}.scan-preset-actions>span{font-size:8px}}

/* Paired physical axes and independent PSF inspection. */
.axis-pairs .matrix-row{grid-template-columns:72px minmax(0,1fr) minmax(0,1fr)}.axis-pairs .matrix-row>span{font-family:var(--ui);font-size:10px}.axis-pairs .matrix-row>span small{display:block;color:var(--muted);font-size:9px}.mapping-layout{display:grid;grid-template-columns:1fr 1fr;gap:26px;align-items:start}.mapping-left{display:flex;flex-direction:column;gap:22px;min-width:0}.mapping-capture{display:flex;align-items:center;justify-content:space-between;gap:14px;border-block:1px solid var(--line);padding:13px 0;font-size:11px;color:var(--muted)}.mapping-capture strong{font:23px var(--mono);color:var(--cyan);margin-left:10px}.mapping-capture small{font-size:10px}.mapping-left .share-row{grid-template-columns:90px 1fr 58px}.psf-projection{min-width:0}.hist-plot canvas[data-hist]{height:360px}
@media(max-width:850px){.mapping-layout{gap:18px}.mapping-capture{align-items:flex-start;flex-direction:column}}
@media(max-width:570px){.mapping-layout{grid-template-columns:1fr}.hist-plot canvas[data-hist]{height:300px}.mapping-left{gap:16px}}

.psf-projection .heatmap svg{max-height:none}

/* Collapsible section titles should remain easy to discover. */
details>summary{font-weight:700}.subdetails>summary,.explanation>summary,.wave-detail>summary{font-weight:700}

