/* Live B workspace. Python owns physics; current previews and immutable acquisitions are separate. */
'use strict';
const $ = id => document.getElementById(id);
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = value => JSON.parse(JSON.stringify(value));
const get = (object, path) => path.split('.').reduce((v, key) => v?.[key], object);
const set = (object, path, value) => {const parts=path.split('.'), key=parts.pop();parts.reduce((v,k)=>v[k],object)[key]=value;};
const fmt = (n, digits=2) => (Math.abs(Number(n))<.5*10**(-digits)?0:Number(n)).toLocaleString('en-US',{maximumFractionDigits:digits});
const WORKSPACE_KIND=document.body.dataset.lab;
const IS_SCAN=WORKSPACE_KIND==='scan';
const API='/api/experiments/'+WORKSPACE_KIND;
const KEY='spad-'+WORKSPACE_KIND+'-modular-v3';
let data, draft, base, selectedChannels=[0], selectedH, selectedV, windowRange, peakWindow, toastTimer;
let catalog, defaultsForm, previewData, lastResult=null, rawResult=null, currentJob=null, displayedJob=null, editors, previewSerial=0, previewTimer, previewController, pollTimer, loadingConfig=false,viewIsAcquisition=false;
const fieldNames=new Map();
let channelLocator,bMechanism,bHistogram;
const concepts={
 tx:['Tx 发射','单发能量属于配置的 Tx 角域，参考面为 Tx 光学之前。角域内各单元的能量份额归一化、合计为 1，再乘一次 Tx 光学效率；不额外扣除角域外能量。'],
 scene:['场景与传播','当前样例使用同距离、同反射率的扩展朗伯目标，计入大气双程损耗和接收入瞳。场景负责传播，Tx/Rx 分别负责发射与接收光学。'],
 rx:['Rx 成像','构造映射分别使用水平和垂直等效焦距，新工况默认倒置，数据库模式以响应数据为准；所有空间图采用右正左负、上正下负。PSF 再按完整像素积分，得到 PDE/FF 前的入射光子。'],
 spad:['SPAD 物理像素','物理像素是光学映射和器件状态的基本单位。PDE/FF 将入射光子转为候选雪崩，器件死时间决定哪些雪崩能实际发生。'],
 readout:['读出通道','每个通道由一组物理 SPAD 构成。读出逻辑和 TDC 决定最终时间戳；通道编号、像素坐标与角度单元分别管理。']
};
function help(path){return data.help.experiments?.[path]||data.help[path.split('.').at(-1)]||{};}
function numeric(path,label,unit='',wide=false){unit=LidarUnits.unit(path,unit);fieldNames.set(path,label);const h=help(path);return `<label class="field ${wide?'wide':''}" title="${esc(h.description||label)}"><span class="field-title">${esc(label)}</span><span class="input-unit"><input type="number" step="any" data-path="${path}" value="${esc(LidarUnits.display(get(draft,path),path))}" aria-label="${esc(label)}">${unit?`<span class="unit">${esc(unit)}</span>`:''}</span></label>`;}
function select(path,label,options){fieldNames.set(path,label);return `<label class="field wide" title="${esc(help(path).description||label)}"><span>${label}</span><select data-path="${path}" aria-label="${label}">${options.map(([v,l])=>`<option value="${v}" ${get(draft,path)===v?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function matrix(title,unit,col1,col2,rows){return `<div class="compact-matrix"><div class="matrix-head"><span>${title}</span><span class="unit">${unit}</span></div><div class="matrix-row headers"><span></span><span>${col1}</span><span>${col2}</span></div>${rows.map(([axis,p1,p2])=>`<div class="matrix-row"><span>${axis}</span>${[p1,p2].map((path,i)=>{const label=title+' '+axis+' '+[col1,col2][i];fieldNames.set(path,label);return `<label><input type="number" step="any" data-path="${path}" value="${esc(LidarUnits.display(get(draft,path),path))}" aria-label="${label}" title="${esc(help(path).description||label)}"></label>`;}).join('')}</div>`).join('')}</div>`;}
function toggle(path,label){fieldNames.set(path,label);return `<label class="toggle-row"><span>${label}</span><span class="switch"><input type="checkbox" data-path="${path}" ${get(draft,path)?'checked':''} aria-label="${label}"></span></label>`;}
function subhead(title){return `<div class="subhead">${title}</div>`;}
function group(id,code,title,summary,body,open=false){return `<details class="parameter-group" data-group="${id}" ${open?'open':''}><summary><span class="group-text"><strong>${title}</strong><small>${summary}</small></span><span class="group-code">${code}</span></summary><div class="group-body">${body}</div></details>`;}
function curveEditor(kind,label){fieldNames.set('spectral_inputs.'+kind,label+'配置');return `<details class="subdetails"><summary>${label}</summary><div class="curve-editor" id="curve-${kind}"></div></details>`;}
function axisPairs(title,rows){return `<div class="compact-matrix axis-pairs"><div class="matrix-head"><span>${title}</span><span class="unit">H / V</span></div><div class="matrix-row headers"><span>参数</span><span>H / x</span><span>V / y</span></div>${rows.map(([label,unit,h,v])=>`<div class="matrix-row"><span>${label}<small>${unit}</small></span>${[h,v].map((path,i)=>{const name=title+' '+label+' '+['H','V'][i];fieldNames.set(path,name);return `<label><input type="number" step="any" data-path="${path}" value="${esc(LidarUnits.display(get(draft,path),path))}" aria-label="${name}" title="${esc(help(path).description||name)}"></label>`;}).join('')}</div>`).join('')}</div>`;}
function renderParameters(){
 const o=draft.optics,d=draft.device,r=draft.readout,t=draft.timing;
 let opened={};document.querySelectorAll('.parameter-group').forEach(el=>opened[el.dataset.group]=el.open);
 if(!Object.keys(opened).length){try{opened=JSON.parse(localStorage.getItem(KEY+'-open')||'{}');}catch{}}
 const m=(...args)=>matrix(...args),n=(...args)=>numeric(...args),s=(...args)=>select(...args);
 const tx=subhead('光源与发射效率')+`<div class="field-grid">${n('optics.wavelength_nm','激光波长','nm')}${n('optics.pulse_average_power_w','单脉冲等效平均功率 · Tx前','W')}${s('optics.pulse_shape','时间脉冲形状',[['gaussian','高斯脉冲'],['rectangular','矩形脉冲']])}${n('optics.pulse_fwhm_ps','脉宽 FWHM','ps')}${n('optics.tx_efficiency','Tx 光学效率')}</div>`+subhead('发射角分布')+`<div class="field-grid">${s('optics.tx_model','Tx 分布模型',[['gaussian','高斯角分布'],['super_gaussian','超高斯角分布'],['uniform','角域内均匀分布'],['dataset','导入光学数据库']])}</div><div data-visible="tx-gaussian">${m('光束角参数','mrad','角中心','FWHM',[['H','optics.tx_center_h_mrad','optics.tx_fwhm_h_mrad'],['V','optics.tx_center_v_mrad','optics.tx_fwhm_v_mrad']])}</div><div data-visible="tx-super">${axisPairs('H/V 超高斯阶数',[['阶数 m','','optics.tx_order_h','optics.tx_order_v']])}<p class="field-note">m=1 为高斯，指数为 2m；宽度使用上方 FWHM。</p></div><details class="subdetails"><summary>角域与覆盖范围</summary>${m('构造 Tx 角域','mrad','最小值','最大值',[['H','optics.angle_h_min_mrad','optics.angle_h_max_mrad'],['V','optics.angle_v_min_mrad','optics.angle_v_max_mrad']])}<p class="field-note">此角域内份额归一化，E=P等效×脉宽（高斯用FWHM）全部分配到域内；Tx效率另计一次。Rx接收域独立，背景不跟随Tx改变。</p></details><p class="field-note" data-visible="tx-dataset">数据库模式使用文件的角域，Tx 份额在域内归一化；审计保留原始总和，Rx PSF 不补偿边缘损失。</p>`;
 const scene=subhead('目标')+`<div class="field-grid">${n('optics.range_m','目标距离','m')}${n('optics.target_reflectivity','目标反射率')}</div>`+subhead('传播')+`<div class="field-grid">${n('optics.atmospheric_one_way_transmission','单程大气透过率')}${n('optics.overlap_factor','Tx / Rx 重叠因子')}</div>${IS_SCAN?scanMotionFields():'<p class="field-note">当前模型：同距离的扩展朗伯目标。</p>'}`;
 const rx=`<div class="optics-files"><label class="file-button">导入光学数据<input id="importOpticalData" type="file" accept=".json,.yaml,.yml"></label><button id="exportOpticalData" class="text-button">导出当前光学数据</button></div>`+subhead('接收入瞳')+`<div class="field-grid">${s('optics.rx_aperture_shape','入瞳形状',[['rectangle','矩形'],['ellipse','椭圆'],['circle','圆形']])}<div class="field wide" data-visible="aperture-axes">${axisPairs('入瞳全轴尺寸',[['全尺寸','mm','optics.rx_aperture_width_mm','optics.rx_aperture_height_mm']])}</div><div class="field wide" data-visible="aperture-circle">${n('optics.rx_aperture_mm','入瞳直径','mm')}</div></div>`+subhead('位置映射与 PSF')+`<div class="field-grid">${s('optics.rx_model','像面映射模型',[['gaussian_psf','几何映射 + 高斯 PSF'],['super_gaussian_psf','几何映射 + 超高斯 PSF'],['uniform_pixel','均匀像素分配'],['dataset','导入光学数据库']])}<div class="field wide" data-visible="rx-synthetic"><div class="field-grid">${n('optics.rx_efficiency','Rx 收光效率')}${s('optics.mapping_mode','几何映射方向',[['inverted','倒置成像（新工况）'],['legacy_upright','历史正向映射']])}</div></div></div><div data-visible="rx-gaussian">${axisPairs('H/V 成像参数',[['等效焦距','mm','optics.focal_length_h_mm','optics.focal_length_v_mm'],['像面偏移','μm','optics.rx_offset_x_um','optics.rx_offset_y_um']])}${axisPairs('H/V PSF 宽度',[['标准差 σ','μm','optics.psf_sigma_h_um','optics.psf_sigma_v_um']])}<div data-visible="rx-super">${axisPairs('H/V PSF 阶数',[['阶数 m','','optics.psf_order_h','optics.psf_order_v']])}</div><p class="field-note">σ_H / σ_V 是实际标准差；超高斯使用指数 2m，m=1 为高斯。H/V 独立，像面外能量仍保留为损失。</p></div><details class="subdetails" data-visible="rx-synthetic"><summary>构造 Rx 数据库覆盖</summary>${m('Rx 角度覆盖域','mrad','最小值','最大值',[['H','optics.rx_angle_h_min_mrad','optics.rx_angle_h_max_mrad'],['V','optics.rx_angle_v_min_mrad','optics.rx_angle_v_max_mrad']])}</details><p class="field-note" data-visible="rx-dataset">数据库模式使用文件中的实际像素边界、效率与 PSF，构造参数不生效。</p>${curveEditor('filter','滤光片透过率')}`;
 const spad=subhead('像素与探测响应')+`<div class="field-grid"><div data-visible="pixel-pitch">${n('optics.pixel_pitch_um','像素节距','μm')}</div>${n('device.fill_factor','填充因子 FF')}${s('device.detector_operation','SPAD 工作方式',[['gated','仅门内工作'],['free_running','持续工作 / 门内记录']])}</div>${curveEditor('pde','PDE 光谱')}`+subhead('器件噪声与恢复')+`<div class="field-grid">${n('device.dcr_cps_per_spad','暗计数 / SPAD','cps')}${n('device.other_noise_cps_per_spad','其他随机噪声','cps')}${n('device.spad_dead_time_ns','SPAD 死时间','ns')}${n('device.spad_jitter_fwhm_ps','SPAD 抖动 FWHM','ps')}</div>`;
 const modes=Object.entries(data.readout_modes).filter(([k,v])=>k!=='analytic_reference'&&v?.label).map(([k,v])=>[k,v.label]);
 const readout=subhead('通道布局与空间分组')+m('二维布局','个','通道数量','每通道 binning',[['H','optics.channels_h','device.H_binning'],['V','optics.channels_v','device.V_binning']])+`<div class="derived" id="readoutLayoutSummary" aria-live="polite">当前参数布局：等待 Python 校验…</div>`+subhead('电子读出')+`<div class="field-grid">${s('readout.readout_mode','读出架构',modes)}${n('readout.tdc_bin_ps','TDC 时间 bin','ps')}${n('readout.tdc_dead_time_ns','TDC 死时间','ns')}${n('readout.other_jitter_fwhm_ps','电子学抖动 FWHM','ps')}${n('optics.calibration_delay_ns','标定延迟','ns')}</div><details class="subdetails"><summary>TDC 容量与符合逻辑</summary><div class="field-grid">${n('readout.tdc_count','共享 TDC 个数')}${n('readout.tdc_max_hits_per_cycle','每 TDC 记录上限')}${n('readout.or_pulse_width_ns','OR 脉宽','ns')}${n('readout.coincidence_window_ns','符合时间窗','ns')}${n('readout.coincidence_threshold','符合阈值')}</div><p class="field-note">各项仅在所选读出架构适用时生效，详见参数说明。</p></details>`;
 const background=toggle('optics.solar_enabled','太阳光')+`<div data-visible="solar"><div class="field-grid">${n('optics.solar_illuminance_lux','目标面太阳照度','lux')}${n('optics.solar_reflectivity','太阳背景灰反射率')}</div>${curveEditor('solar','太阳光谱')}</div><p class="field-note" data-visible="no-solar">已关闭。开启后配置照度与光谱。</p>`+subhead('其他环境光')+toggle('optics.other_light_enabled','其他环境光')+`<div data-visible="ambient"><div class="field-grid">${n('optics.other_light_scale','环境光强度倍率')}</div>${curveEditor('other','环境光谱')}</div><p class="field-note" data-visible="no-ambient">已关闭。开启后配置强度与光谱。</p>`;
 const acquisition=IS_SCAN?scanAcquisitionFields():subhead('采集时序')+`<div class="field-grid">${n('timing.period_ns','发射周期','ns')}${n('timing.laser_shots','slot 内累计发数 N','发')}${n('timing.gate_start_ns','接收门起点','ns')}${n('timing.gate_width_ns','单 gate 接收门宽','ns')}</div>`+subhead('随机采样与统计')+`<div class="field-grid">${n('rng_seed','随机种子')}${n('timing.monte_carlo_trials','统计重复次数 M','次')}</div><div class="derived">含噪重复采集：<b>${draft.timing.monte_carlo_trials}</b> 次<br>噪声参考：<b>${catalog.algorithms.b_noise_reference==='candidate_scalar'?'解析标量 · 无额外采集':catalog.algorithms.readout_expected_trials+' 次关激光采集'}</b></div><p class="field-note">含噪重复统计包括首次观测；当前噪声参考策略和初始化方式见算法配置。</p>`;
